over='''{% extends 'rebuild/base.html' %}{% block title %}Zeiterfassung · KAYI{% endblock %}{% block content %}<div class="nx-pagehead"><div><div class="nx-kicker">Arbeitszeit</div><h1>Zeiterfassung</h1><p>Projektbezogene Arbeitszeiten, laufende Einsätze und Korrekturen auf einen Blick.</p></div><div class="nx-actions"><a class="nx-btn nx-btn-primary" href="{% url 'next-field' %}">Monteur-App öffnen</a></div></div><section class="nx-time-kpis"><div><small>Heute</small><b>{{ today_hours }} h</b><span>Netto-Arbeitszeit</span></div><div><small>Diese Woche</small><b>{{ week_hours }} h</b><span>ab {{ week_start|date:'d.m.' }}</span></div><div class="{% if running_count %}is-running{% endif %}"><small>Laufend</small><b>{{ running_count }}</b><span>aktive Buchungen</span></div></section><section class="nx-card nx-time-filter-card"><form method="get" class="nx-time-filters">{% if not field_user %}<label><span>Mitarbeiter</span><select class="nx-control" name="employee"><option value="">Alle</option>{% for i in employees %}<option value="{{ i.pk }}" {% if employee_filter == i.pk|stringformat:'s' %}selected{% endif %}>{{ i.first_name }} {{ i.last_name }}</option>{% endfor %}</select></label>{% endif %}<label><span>Projekt</span><select class="nx-control" name="project"><option value="">Alle</option>{% for i in projects %}<option value="{{ i.pk }}" {% if project_filter == i.pk|stringformat:'s' %}selected{% endif %}>{{ i.number }} · {{ i.title }}</option>{% endfor %}</select></label><label><span>Von</span><input class="nx-control" type="date" name="date_from" value="{{ date_from }}"></label><label><span>Bis</span><input class="nx-control" type="date" name="date_to" value="{{ date_to }}"></label><div class="nx-time-filter-actions"><button class="nx-btn nx-btn-primary">Filtern</button><a class="nx-btn nx-btn-ghost" href="{% url 'next-time' %}">Zurücksetzen</a></div></form></section><section class="nx-card"><div class="nx-card-head"><div><h2>Arbeitszeiten</h2><p>{% if field_user and employee %}{{ employee.first_name }} {{ employee.last_name }} · nur deine Buchungen.{% else %}Büroansicht · alle Mitarbeiter und Projekte.{% endif %}</p></div></div><div class="nx-table-wrap nx-time-table-wrap"><table class="nx-table nx-time-table"><thead><tr><th>Datum</th><th>Mitarbeiter</th><th>Projekt</th><th>Start / Ende</th><th>Dauer</th><th>Pause</th><th>Status</th>{% if not field_user %}<th></th>{% endif %}</tr></thead><tbody>{% for e in entries %}<tr class="{% if not e.ended_at %}is-running{% endif %}"><td data-label="Datum">{{ e.started_at|date:'d.m.Y' }}</td><td data-label="Mitarbeiter"><strong>{{ e.employee.first_name }} {{ e.employee.last_name }}</strong></td><td data-label="Projekt">{% if e.project %}<a href="{% url 'next-project-detail' e.project.pk %}">{{ e.project.number }} · {{ e.project.title }}</a>{% else %}—{% endif %}</td><td data-label="Start / Ende">{{ e.started_at|date:'H:i' }} → {% if e.ended_at %}{{ e.ended_at|date:'H:i' }}{% else %}<span class="nx-badge nx-badge-success">läuft</span>{% endif %}</td><td data-label="Dauer"><strong>{{ e.ui_duration }}</strong></td><td data-label="Pause">{{ e.break_minutes }} min</td><td data-label="Status">{% if e.approved %}<span class="nx-badge nx-badge-success">Freigegeben</span>{% else %}<span class="nx-badge">Offen</span>{% endif %}</td>{% if not field_user %}<td data-label="Büro"><a class="nx-btn nx-btn-ghost nx-time-edit" href="{% url 'next-time-entry-edit' e.pk %}">Korrigieren</a></td>{% endif %}</tr>{% empty %}<tr><td colspan="8"><div class="nx-empty"><b>Noch keine Arbeitszeiten erfasst.</b><span>Start über „Arbeit starten“ in der Monteur-App.</span></div></td></tr>{% endfor %}</tbody></table></div></section>{% endblock %}'''
w('templates/rebuild/time_overview.html',over)
edit='''{% extends 'rebuild/base.html' %}{% block title %}Arbeitszeit korrigieren · KAYI{% endblock %}{% block content %}<div class="nx-pagehead"><div><div class="nx-kicker">Zeiterfassung · Büro</div><h1>Arbeitszeit korrigieren</h1><p>{{ entry.employee.first_name }} {{ entry.employee.last_name }} · {% if entry.project %}{{ entry.project.number }} · {{ entry.project.title }}{% endif %}</p></div><a class="nx-btn" href="{% url 'next-time' %}">← Zeiterfassung</a></div><section class="nx-card nx-time-edit-card">{% if error %}<div class="nx-global-form-errors"><b>Bitte Eingaben prüfen.</b><p><span>{{ error }}</span></p></div>{% endif %}<form method="post">{% csrf_token %}<div class="next-grid"><label class="next-field"><span>Start</span><input class="next-control" type="datetime-local" name="started_at" value="{{ entry.started_at|date:'Y-m-d\\TH:i' }}" required></label><label class="next-field"><span>Ende</span><input class="next-control" type="datetime-local" name="ended_at" value="{% if entry.ended_at %}{{ entry.ended_at|date:'Y-m-d\\TH:i' }}{% endif %}"></label><label class="next-field"><span>Pause (Min.)</span><input class="next-control" type="number" min="0" max="1440" name="break_minutes" value="{{ entry.break_minutes|default:0 }}"></label><label class="next-field"><span>Status</span><select class="next-control" name="approved"><option value="0" {% if not entry.approved %}selected{% endif %}>Offen</option><option value="1" {% if entry.approved %}selected{% endif %}>Freigegeben</option></select></label><label class="next-field next-span-2"><span>Notiz</span><textarea class="next-control" name="description">{{ entry.description }}</textarea></label></div><div class="next-actions"><a class="nx-btn" href="{% url 'next-time' %}">Abbrechen</a><button class="nx-btn nx-btn-primary">Korrektur speichern</button></div></form></section>{% endblock %}'''
